sql:
CREATE TABLE Activities (
  id INTEGER PRIMARY KEY,
  description TEXT,
  location TEXT,
  date TEXT
);

CREATE TABLE Reminders (
  id INTEGER PRIMARY KEY,
  description TEXT,
  due_date TEXT
);

CREATE TABLE Events (
  id INTEGER PRIMARY KEY,
  description TEXT,
  location TEXT,
  date TEXT
);

CREATE TABLE Cars (
  id INTEGER PRIMARY KEY,
  model TEXT,
  year INTEGER,
  plate TEXT
);

CREATE TABLE Groceries (
  id INTEGER PRIMARY KEY,
  store TEXT,
  amount INTEGER
);

CREATE TABLE PassportRenewals (
  id INTEGER PRIMARY KEY,
  renewal_date TEXT
);

CREATE TABLE SportsAchievements (
  id INTEGER PRIMARY KEY,
  type TEXT,
  description TEXT,
  time TEXT
);

CREATE TABLE GymMemberships (
  id INTEGER PRIMARY KEY,
  gym_name TEXT,
  membership_cost REAL,
  start_date TEXT
);
